<template><div class="list"><div v-for="(_,i) in modelValue" :key="i" class="row"><input :value="modelValue[i]" :aria-label="`${label} ${i+1}`" @input="update(i,($event.target as HTMLInputElement).value)"><button type="button" :aria-label="`删除${label} ${i+1}`" @click="remove(i)">删除</button></div><button type="button" class="add" @click="$emit('update:modelValue',[...modelValue,''])">+ 添加{{ label }}</button></div></template>
<script setup lang="ts">const props=defineProps<{modelValue:string[];label:string}>();const emit=defineEmits<{'update:modelValue':[value:string[]]}>();function update(i:number,v:string){const next=[...props.modelValue];next[i]=v;emit('update:modelValue',next)}function remove(i:number){const next=[...props.modelValue];next.splice(i,1);emit('update:modelValue',next)}</script>
<style scoped>.list{display:grid;gap:6px}.row{display:grid;grid-template-columns:1fr auto;gap:6px}.add{justify-self:start}</style>
